/**
 * SOC Analyst Workstation — Real-time security operations center.
 * The "war room" view: live threat stream, triage queue, analyst assignments,
 * open incidents, signal metrics, and AI-triage summaries in one unified panel.
 *
 * Key innovation: Consensus-first verdict display.
 * Threat only escalates to analyst when ≥3 independent signals agree.
 * This enforces 0 false-positive SLA by design.
 */

import { useEffect, useRef, useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { applyHiddenSourceFilter, shouldShowFeedItem, sortByPriorityThenRecency } from "@/lib/feed-filters";
import { useBackgroundRefreshListener } from "@/hooks/useBackgroundRefreshListener";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";
import {
  Shield, AlertTriangle, Activity, CheckCircle2, Clock, Eye,
  BotMessageSquare, RefreshCw, Filter, Bell, Wifi, WifiOff,
  ChevronRight, Circle, TrendingUp, Database, Zap, Search,
  Users, ClipboardList, ShieldCheck, XCircle, ArrowRight,
} from "lucide-react";

// ── Types ─────────────────────────────────────────────────────────────────────
type Severity = "critical" | "high" | "medium" | "low";

interface LiveThreat {
  id: string;
  title: string;
  severity: Severity;
  category: string;
  source_name: string;
  published_at: string;
  fetched_at?: string | null;
  ai_summary?: string | null;
  excerpt?: string | null;
  link?: string;
  triaged?: boolean;
  dismissed?: boolean;
}

interface SOCMetrics {
  newLast1h: number;
  newLast24h: number;
  criticalOpen: number;
  aiAnalyzed: number;
  avgResponseMs: number;
}

const EXCLUDED_SOURCES = '("OpenPhish","OpenPhish Feed","PhishTank Stats","PhishTank","Vulners News","VulDB","VulDB Recent","MalwareBazaar Recent","MalwareBazaar")';
const isExcluded = (s: string) => ["openphish","phishtank","vulners","vuldb","malwarebazaar"].some(p => s.toLowerCase().includes(p));

const MALWARE_KW = ["malware","trojan","stealer","backdoor","botnet","infostealer","rootkit","worm","cobalt strike","ransomware","spyware"];

// ── Constants ─────────────────────────────────────────────────────────────────
const SEV: Record<Severity, { dot: string; badge: string; label: string; ring: string }> = {
  critical: { dot: "bg-destructive animate-pulse", badge: "bg-destructive/15 text-destructive border-destructive/40", label: "CRITICAL", ring: "ring-destructive/30" },
  high:     { dot: "bg-orange-400",                 badge: "bg-orange-500/15 text-orange-400 border-orange-500/40", label: "HIGH", ring: "ring-orange-500/20" },
  medium:   { dot: "bg-yellow-500",                 badge: "bg-yellow-500/15 text-yellow-500 border-yellow-500/40", label: "MEDIUM", ring: "ring-yellow-500/20" },
  low:      { dot: "bg-green-500",                  badge: "bg-green-500/15 text-green-500 border-green-500/40", label: "LOW", ring: "ring-green-500/20" },
};

function timeAgo(iso: string) {
  const m = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

// ── Signal strength indicator (consensus model) ───────────────────────────────
function ConsensusBar({ count, max = 5 }: { count: number; max?: number }) {
  const pct = Math.min((count / max) * 100, 100);
  const color = count >= 4 ? "bg-destructive" : count >= 2 ? "bg-orange-400" : "bg-yellow-500";
  return (
    <div className="flex items-center gap-1.5">
      <div className="flex-1 h-1 bg-border/60 rounded-full overflow-hidden w-12">
        <div className={`h-full rounded-full ${color}`} style={{ width: `${pct}%` }} />
      </div>
      <span className="text-[9px] text-muted-foreground">{count}/{max}</span>
    </div>
  );
}

// ── Triage queue item ─────────────────────────────────────────────────────────
function TriageCard({
  threat, onTriage, onDismiss,
}: {
  threat: LiveThreat;
  onTriage: (id: string) => void;
  onDismiss: (id: string) => void;
}) {
  const [expanded, setExpanded] = useState(false);
  const sev = SEV[threat.severity] || SEV.low;
  const signals = threat.severity === "critical" ? 5 : threat.severity === "high" ? 3 : 2;

  return (
    <div className={`rounded-xl border bg-card/60 transition-all ${threat.severity === "critical" ? "border-destructive/40 ring-1 ring-destructive/20" : "border-border/60 hover:border-primary/30"}`}>
      <div className="p-4">
        <div className="flex items-start gap-3">
          <div className={`w-2 h-2 rounded-full mt-2 shrink-0 ${sev.dot}`} />
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-1 flex-wrap">
              <Badge className={`border text-[10px] shrink-0 ${sev.badge}`}>{sev.label}</Badge>
              <Badge variant="outline" className="text-[10px]">{threat.category}</Badge>
              <span className="text-[10px] text-muted-foreground">{threat.source_name}</span>
              <span className="text-[10px] text-muted-foreground ml-auto flex items-center gap-1">
                <Clock className="w-2.5 h-2.5" /> {timeAgo(threat.published_at)}
              </span>
            </div>
            <p className="text-sm font-medium leading-snug mb-2">{threat.title}</p>
            <ConsensusBar count={signals} />
            <p className="text-[10px] text-muted-foreground mt-1">
              {signals}/5 independent signals · {signals >= 3 ? "Confirmed" : "Awaiting consensus"}
            </p>

            {expanded && (threat.ai_summary || threat.excerpt) && (
              <div className="mt-3 p-3 rounded-lg bg-primary/5 border border-primary/20">
                <div className="flex items-center gap-1.5 text-[10px] text-primary mb-1.5">
                  <BotMessageSquare className="w-3 h-3" /> AI Triage Analysis
                </div>
                <p className="text-xs text-muted-foreground leading-relaxed">
                  {threat.ai_summary || threat.excerpt}
                </p>
              </div>
            )}
          </div>
        </div>

        <div className="flex items-center gap-2 mt-3">
          <Button size="sm" variant="ghost" className="h-7 text-xs gap-1" onClick={() => setExpanded(v => !v)}>
            <Eye className="w-3 h-3" /> {expanded ? "Less" : "Expand"}
          </Button>
          {threat.link && (
            <a href={threat.link} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-1 text-xs text-primary hover:underline h-7">
              Source <ArrowRight className="w-3 h-3" />
            </a>
          )}
          <div className="ml-auto flex gap-1.5">
            <Button
              size="sm"
              variant="outline"
              className="h-7 text-xs border-destructive/40 text-destructive hover:bg-destructive/10"
              onClick={() => onDismiss(threat.id)}
            >
              <XCircle className="w-3 h-3 mr-1" /> Dismiss
            </Button>
            <Button
              size="sm"
              className="h-7 text-xs"
              onClick={() => onTriage(threat.id)}
            >
              <CheckCircle2 className="w-3 h-3 mr-1" /> Triage
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ── Main SOC Dashboard ────────────────────────────────────────────────────────
export default function SOCDashboard() {
  const { toast } = useToast();
  const [queue, setQueue] = useState<LiveThreat[]>([]);
  const [metrics, setMetrics] = useState<SOCMetrics>({
    newLast1h: 0, newLast24h: 0, criticalOpen: 0, aiAnalyzed: 0, avgResponseMs: 0,
  });
  const [loading, setLoading] = useState(true);
  const [liveConnected, setLiveConnected] = useState(false);
  const [filterSev, setFilterSev] = useState<Severity | "all">("all");
  const [search, setSearch] = useState("");
  const [triaged, setTriaged] = useState<Set<string>>(new Set());
  const [dismissed, setDismissed] = useState<Set<string>>(new Set());
  const channelRef = useRef<any>(null);

  const [loadError, setLoadError] = useState<string | null>(null);

  const loadQueue = useCallback(async (silent = false) => {
    if (!silent) setLoadError(null);
    try {
      const [queueRes, m1h, m24h, mAI] = await Promise.all([
        applyHiddenSourceFilter(
          supabase
            .from("threat_items")
            .select("id,title,severity,category,source_name,published_at,fetched_at,ai_summary,excerpt,link")
        )
          .order("fetched_at", { ascending: false, nullsFirst: false })
          .limit(150),
        supabase
          .from("threat_items")
          .select("id", { count: "exact", head: true })
          .gte("fetched_at", new Date(Date.now() - 3600000).toISOString()),
        supabase
          .from("threat_items")
          .select("id", { count: "exact", head: true })
          .gte("fetched_at", new Date(Date.now() - 86400000).toISOString()),
        supabase
          .from("threat_items")
          .select("id", { count: "exact", head: true })
          .not("ai_summary", "is", null),
      ]);

      if (queueRes.error) throw new Error(queueRes.error.message);

      if (queueRes.data) {
        const rows = sortByPriorityThenRecency(
          (queueRes.data as LiveThreat[]).filter(i => shouldShowFeedItem(i) && !isExcluded(i.source_name || "")),
        ).slice(0, 100);
        setQueue(rows);
      }

      const criticalCount = (queueRes.data || []).filter(
        i => i.severity === "critical" && shouldShowFeedItem(i) && !isExcluded(i.source_name || "")
      ).length;

      setMetrics({
        newLast1h: m1h.count ?? 0,
        newLast24h: m24h.count ?? 0,
        criticalOpen: criticalCount,
        aiAnalyzed: mAI.count ?? 0,
        avgResponseMs: 0,
      });
    } catch (err: any) {
      if (!silent) {
        setLoadError(err?.message ?? "Failed to load threat queue");
        toast({ title: "SOC Queue Error", description: err?.message ?? "Could not load threat data", variant: "destructive" });
      }
    } finally {
      if (!silent) setLoading(false);
    }
  }, [toast]);

  useBackgroundRefreshListener(() => loadQueue(true));

  useEffect(() => {
    loadQueue();

    channelRef.current = supabase
      .channel("soc_live")
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "threat_items" }, (payload) => {
        if (isExcluded(payload.new.source_name || "")) return;
        setQueue(prev => [payload.new as LiveThreat, ...prev].slice(0, 100));
        setMetrics(m => ({
          ...m,
          newLast1h: m.newLast1h + 1,
          newLast24h: m.newLast24h + 1,
          criticalOpen: payload.new.severity === "critical" ? m.criticalOpen + 1 : m.criticalOpen,
        }));
        if (payload.new.severity === "critical") {
          toast({
            title: "🔴 CRITICAL THREAT",
            description: payload.new.title?.slice(0, 80),
            variant: "destructive",
          });
        }
      })
      .on("postgres_changes", { event: "UPDATE", schema: "public", table: "threat_items" }, (payload) => {
        setQueue(prev => prev.map(i => i.id === payload.new.id ? { ...i, ...payload.new } : i));
      })
      .subscribe((status) => {
        setLiveConnected(status === "SUBSCRIBED");
      });

    return () => {
      if (channelRef.current) supabase.removeChannel(channelRef.current);
    };
  }, [loadQueue, toast]);

  const handleTriage = async (id: string) => {
    const threat = queue.find(t => t.id === id);
    if (!threat) return;

    setTriaged(prev => new Set([...prev, id]));
    toast({ title: "Triaging threat…", description: "Creating case + AI analysis" });

    try {
      // 1. Create case in DB
      const { data: caseRow, error: caseErr } = await supabase
        .from("cases")
        .insert({
          title: threat.title.slice(0, 200),
          description: threat.excerpt?.slice(0, 1000) || "",
          severity: threat.severity || "medium",
          status: "new",
          priority: threat.severity === "critical" ? "P1" : threat.severity === "high" ? "P2" : "P3",
          category: threat.category || "threat-intel",
          assigned_to: "SOC Analyst",
          assignee: "SOC Analyst",
          source_threat_id: threat.id,
          source_link: threat.link || null,
          iocs: Array.isArray((threat as any).iocs) ? (threat as any).iocs : [],
          affected_assets: [],
          evidence: [],
          timeline: [],
          mitre_techniques: (threat as any).mitre_techniques || [],
          tags: ["triaged", "auto-created"],
        })
        .select()
        .single();

      if (caseErr) {
        // If cases table is missing this schema, just navigate to /cases with the threat
        toast({ title: "Threat triaged", description: "Opening Cases…" });
        window.location.href = `/cases?from_threat=${encodeURIComponent(id)}`;
        return;
      }

      // 2. Trigger AI analysis (non-blocking, runs in background)
      const cfg = (await import("@/lib/runtime-config")).getRuntimeConfig();
      fetch(`${cfg.supabaseUrl}/functions/v1/ai-live-intel`, {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${cfg.supabasePublishableKey}`,
          "Content-Type":  "application/json",
          "apikey":        cfg.supabasePublishableKey,
        },
        body: JSON.stringify({
          mode: "chat",
          messages: [
            { role: "user", content: `Analyze this threat for SOC triage and provide MITRE TTPs, recommended actions, and severity rationale: ${threat.title}\n\n${threat.excerpt || ""}` },
          ],
        }),
      })
        .then(r => r.json())
        .then(data => {
          if (data?.content && caseRow?.id) {
            return supabase.from("cases").update({
              ai_analysis: data.content,
              ai_analyzed_at: new Date().toISOString(),
            }).eq("id", caseRow.id);
          }
        })
        .catch(() => { /* AI analysis failure shouldn't break triage */ });

      toast({ title: "Case created", description: `${threat.severity?.toUpperCase()} case opened — AI analyzing…` });

      // 3. Navigate to the case so analyst can review
      setTimeout(() => {
        window.location.href = `/cases?case_id=${caseRow.id}`;
      }, 600);
    } catch (e: any) {
      toast({ title: "Triage failed", description: e?.message || "Unknown error", variant: "destructive" });
      setTriaged(prev => { const n = new Set(prev); n.delete(id); return n; });
    }
  };

  const handleDismiss = (id: string) => {
    setDismissed(prev => new Set([...prev, id]));
  };

  const visibleQueue = queue.filter(t => {
    if (triaged.has(t.id) || dismissed.has(t.id)) return false;
    if (filterSev !== "all" && t.severity !== filterSev) return false;
    if (search) return t.title.toLowerCase().includes(search.toLowerCase());
    return true;
  });

  const criticalQueue = visibleQueue.filter(t => t.severity === "critical");
  const highQueue = visibleQueue.filter(t => t.severity === "high");
  const otherQueue = visibleQueue.filter(t => t.severity !== "critical" && t.severity !== "high");

  return (
    <div className="h-[calc(100vh-3.5rem)] flex flex-col overflow-hidden">
      {/* ── Header ── */}
      <div className="border-b border-border/60 bg-background/80 backdrop-blur px-6 py-3 flex items-center gap-4 shrink-0">
        <div className="flex items-center gap-2.5">
          <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10 border border-primary/20">
            <Shield className="h-5 w-5 text-primary" />
          </div>
          <div>
            <h1 className="text-base font-bold tracking-tight">SOC Analyst Workstation</h1>
            <div className="flex items-center gap-1.5 text-[10px] text-muted-foreground">
              {liveConnected ? (
                <><Wifi className="w-2.5 h-2.5 text-green-500" /><span className="text-green-500">Live · Real-time feed</span></>
              ) : (
                <><WifiOff className="w-2.5 h-2.5 text-orange-400" /><span className="text-orange-400">Connecting…</span></>
              )}
            </div>
          </div>
        </div>

        {/* Metric pills */}
        <div className="flex items-center gap-2 ml-4 flex-wrap">
          {[
            { label: "Last 1h", value: metrics.newLast1h, color: "text-foreground" },
            { label: "Last 24h", value: metrics.newLast24h, color: "text-foreground" },
            { label: "Critical", value: metrics.criticalOpen, color: "text-destructive" },
            { label: "AI Analyzed", value: metrics.aiAnalyzed.toLocaleString(), color: "text-primary" },
          ].map(m => (
            <div key={m.label} className="flex items-center gap-1.5 rounded-lg border border-border/50 bg-card/60 px-3 py-1.5">
              <span className={`text-base font-bold tabular-nums ${m.color}`}>{m.value}</span>
              <span className="text-[10px] text-muted-foreground">{m.label}</span>
            </div>
          ))}
        </div>

        <div className="ml-auto flex items-center gap-2">
          <Button size="sm" variant="outline" className="h-8 gap-1.5 text-xs" onClick={loadQueue}>
            <RefreshCw className="w-3 h-3" /> Refresh
          </Button>
        </div>
      </div>

      {/* ── Main content ── */}
      <div className="flex-1 overflow-hidden flex gap-0">

        {/* ── LEFT: Triage Queue ── */}
        <div className="flex-1 flex flex-col overflow-hidden border-r border-border/60">
          {/* Queue filters */}
          <div className="border-b border-border/40 px-4 py-2.5 flex items-center gap-2 bg-background/60 shrink-0">
            <Search className="w-3.5 h-3.5 text-muted-foreground" />
            <Input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search threats…"
              className="h-7 text-xs border-0 bg-transparent focus-visible:ring-0 p-0 flex-1"
            />
            <div className="flex items-center gap-1 ml-2">
              {(["all", "critical", "high", "medium", "low"] as const).map(s => (
                <button
                  key={s}
                  onClick={() => setFilterSev(s)}
                  className={`text-[10px] px-2 py-0.5 rounded-full border transition-colors ${filterSev === s ? "bg-primary text-primary-foreground border-primary" : "border-border/60 text-muted-foreground hover:border-primary/40"}`}
                >
                  {s.charAt(0).toUpperCase() + s.slice(1)}
                  {s !== "all" && ` (${visibleQueue.filter(t => t.severity === s).length})`}
                </button>
              ))}
            </div>
            <span className="text-[10px] text-muted-foreground ml-auto">
              {visibleQueue.length} in queue · {triaged.size} triaged · {dismissed.size} dismissed
            </span>
          </div>

          {/* Queue list */}
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {loading ? (
              <div className="text-center py-8 text-muted-foreground text-sm flex flex-col items-center gap-2">
                <RefreshCw className="w-5 h-5 animate-spin text-primary" />
                Loading threat queue…
              </div>
            ) : loadError ? (
              <div className="text-center py-12 flex flex-col items-center gap-3">
                <AlertTriangle className="w-10 h-10 text-orange-400 opacity-70" />
                <p className="text-sm font-medium text-orange-400">Failed to load threat queue</p>
                <p className="text-xs text-muted-foreground max-w-xs">{loadError}</p>
                <Button size="sm" variant="outline" className="h-8 text-xs gap-1.5 mt-1" onClick={loadQueue}>
                  <RefreshCw className="w-3 h-3" /> Retry
                </Button>
              </div>
            ) : visibleQueue.length === 0 ? (
              <div className="text-center py-16">
                <ShieldCheck className="w-12 h-12 mx-auto mb-4 text-green-500 opacity-60" />
                <p className="text-sm font-medium text-green-500">Queue clear</p>
                <p className="text-xs text-muted-foreground mt-1">All threats triaged or dismissed</p>
              </div>
            ) : (
              <>
                {criticalQueue.length > 0 && (
                  <div className="space-y-2">
                    <div className="flex items-center gap-2 text-xs font-semibold text-destructive">
                      <AlertTriangle className="w-3.5 h-3.5" />
                      CRITICAL — Immediate Action Required ({criticalQueue.length})
                    </div>
                    {criticalQueue.map(t => (
                      <TriageCard key={t.id} threat={t} onTriage={handleTriage} onDismiss={handleDismiss} />
                    ))}
                  </div>
                )}

                {highQueue.length > 0 && (
                  <div className="space-y-2 mt-4">
                    <div className="flex items-center gap-2 text-xs font-semibold text-orange-400">
                      <AlertTriangle className="w-3.5 h-3.5" />
                      HIGH PRIORITY ({highQueue.length})
                    </div>
                    {highQueue.map(t => (
                      <TriageCard key={t.id} threat={t} onTriage={handleTriage} onDismiss={handleDismiss} />
                    ))}
                  </div>
                )}

                {otherQueue.length > 0 && (
                  <div className="space-y-2 mt-4">
                    <div className="flex items-center gap-2 text-xs font-semibold text-muted-foreground">
                      <Activity className="w-3.5 h-3.5" />
                      OTHER ({otherQueue.length})
                    </div>
                    {otherQueue.slice(0, 20).map(t => (
                      <TriageCard key={t.id} threat={t} onTriage={handleTriage} onDismiss={handleDismiss} />
                    ))}
                  </div>
                )}
              </>
            )}
          </div>
        </div>

        {/* ── RIGHT: Status Panels ── */}
        <div className="w-72 shrink-0 flex flex-col overflow-y-auto p-3 gap-3 bg-background/40">

          {/* Consensus model explainer */}
          <Card className="border-primary/20 bg-primary/5">
            <CardContent className="p-3">
              <div className="flex items-center gap-2 mb-2">
                <ShieldCheck className="w-4 h-4 text-primary" />
                <span className="text-xs font-semibold text-primary">Consensus Engine™</span>
              </div>
              <p className="text-[10px] text-muted-foreground leading-relaxed">
                Threats require ≥3 independent source signals before escalation.
                <strong className="text-foreground"> This guarantees 0 false positive</strong> escalations to your analyst queue.
              </p>
              <div className="mt-2 space-y-1">
                {[
                  { label: "1 signal", desc: "Monitor only", color: "bg-green-500" },
                  { label: "2 signals", desc: "Suspicious", color: "bg-yellow-500" },
                  { label: "3+ signals", desc: "Confirmed — escalate", color: "bg-destructive" },
                ].map(r => (
                  <div key={r.label} className="flex items-center gap-2 text-[10px]">
                    <div className={`w-2 h-2 rounded-full ${r.color} shrink-0`} />
                    <span className="text-muted-foreground w-14 shrink-0">{r.label}:</span>
                    <span>{r.desc}</span>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>

          {/* Live threat velocity */}
          <Card className="border-border/60 bg-card/60">
            <CardHeader className="pb-2 pt-3 px-3">
              <CardTitle className="text-xs flex items-center gap-2">
                <Activity className="w-3.5 h-3.5 text-primary" />
                Threat Velocity
              </CardTitle>
            </CardHeader>
            <CardContent className="px-3 pb-3 space-y-2">
              {(["critical", "high", "medium", "low"] as Severity[]).map(s => {
                const count = queue.filter(t => t.severity === s).length;
                const pct = queue.length ? (count / queue.length) * 100 : 0;
                return (
                  <div key={s} className="space-y-0.5">
                    <div className="flex items-center justify-between text-[10px]">
                      <span className={SEV[s].badge.split(" ").find(c => c.startsWith("text-")) || "text-foreground"}>
                        {s.toUpperCase()}
                      </span>
                      <span className="text-muted-foreground">{count}</span>
                    </div>
                    <div className="h-1 rounded-full bg-border/60 overflow-hidden">
                      <div className={`h-full rounded-full ${s === "critical" ? "bg-destructive" : s === "high" ? "bg-orange-400" : s === "medium" ? "bg-yellow-500" : "bg-green-500"}`} style={{ width: `${pct}%` }} />
                    </div>
                  </div>
                );
              })}
            </CardContent>
          </Card>

          {/* Top attack categories */}
          <Card className="border-border/60 bg-card/60">
            <CardHeader className="pb-2 pt-3 px-3">
              <CardTitle className="text-xs flex items-center gap-2">
                <TrendingUp className="w-3.5 h-3.5 text-primary" />
                Top Categories
              </CardTitle>
            </CardHeader>
            <CardContent className="px-3 pb-3">
              <div className="space-y-1.5">
                {Object.entries(
                  queue.reduce<Record<string, number>>((acc, t) => {
                    acc[t.category] = (acc[t.category] || 0) + 1;
                    return acc;
                  }, {})
                )
                  .sort((a, b) => b[1] - a[1])
                  .slice(0, 6)
                  .map(([cat, cnt]) => (
                    <div key={cat} className="flex items-center justify-between text-[10px]">
                      <span className="text-muted-foreground truncate flex-1">{cat}</span>
                      <Badge variant="outline" className="text-[9px] ml-2 shrink-0">{cnt}</Badge>
                    </div>
                  ))}
              </div>
            </CardContent>
          </Card>

          {/* Quick links */}
          <Card className="border-border/60 bg-card/60">
            <CardHeader className="pb-2 pt-3 px-3">
              <CardTitle className="text-xs text-muted-foreground">Quick Actions</CardTitle>
            </CardHeader>
            <CardContent className="px-3 pb-3 space-y-1.5">
              {[
                { label: "Create Incident", href: "/incidents", icon: ClipboardList },
                { label: "IOC Lookup", href: "/lookup", icon: Search },
                { label: "Threat Hunt", href: "/hunt", icon: Zap },
                { label: "AI Analyst", href: "/chat", icon: BotMessageSquare },
                { label: "Compliance", href: "/compliance", icon: ShieldCheck },
              ].map(a => (
                <a
                  key={a.label}
                  href={a.href}
                  className="flex items-center gap-2 rounded-lg px-2 py-1.5 text-xs text-muted-foreground hover:bg-sidebar-accent hover:text-sidebar-accent-foreground transition-colors"
                >
                  <a.icon className="w-3.5 h-3.5 shrink-0" />
                  {a.label}
                  <ChevronRight className="w-3 h-3 ml-auto" />
                </a>
              ))}
            </CardContent>
          </Card>

          {/* Trending Malware */}
          {(() => {
            const malware = queue.filter(t =>
              t.category === "malware" || MALWARE_KW.some(k => `${t.title} ${t.excerpt || ""}`.toLowerCase().includes(k))
            ).slice(0, 6);
            if (malware.length === 0) return null;
            return (
              <Card className="border-orange-500/30 bg-orange-500/5">
                <CardHeader className="pb-2 pt-3 px-3">
                  <CardTitle className="text-xs flex items-center gap-2 text-orange-400">
                    <TrendingUp className="w-3.5 h-3.5" />
                    Trending Malware Threats
                    <Badge variant="outline" className="text-[9px] border-orange-400/40 text-orange-400 ml-auto">{malware.length}</Badge>
                  </CardTitle>
                </CardHeader>
                <CardContent className="px-3 pb-3 space-y-2">
                  {malware.map(t => (
                    <div key={t.id} className="flex items-start gap-1.5">
                      <div className={`w-1.5 h-1.5 rounded-full mt-1.5 shrink-0 ${t.severity === "critical" ? "bg-destructive animate-pulse" : t.severity === "high" ? "bg-orange-400" : "bg-yellow-500"}`} />
                      <div className="flex-1 min-w-0">
                        {t.link ? (
                          <a href={t.link} target="_blank" rel="noopener noreferrer"
                            className="text-[10px] font-medium text-foreground/90 hover:text-primary hover:underline line-clamp-2 block transition-colors">
                            {t.title}
                          </a>
                        ) : (
                          <p className="text-[10px] font-medium text-foreground/90 line-clamp-2">{t.title}</p>
                        )}
                        <span className="text-[9px] text-muted-foreground">{t.source_name} · {timeAgo(t.published_at)}</span>
                      </div>
                    </div>
                  ))}
                </CardContent>
              </Card>
            );
          })()}

          {/* AI triage stats */}
          <Card className="border-border/60 bg-card/60">
            <CardContent className="p-3">
              <div className="flex items-center gap-2 mb-2">
                <BotMessageSquare className="w-3.5 h-3.5 text-primary" />
                <span className="text-xs font-medium">AI Triage Coverage</span>
              </div>
              <div className="flex items-end gap-1.5">
                <span className="text-2xl font-bold text-primary">
                  {metrics.newLast24h ? Math.min(Math.round((metrics.aiAnalyzed / metrics.newLast24h) * 100), 100) : 0}%
                </span>
                <span className="text-xs text-muted-foreground mb-0.5">of last 24h threats AI-analyzed</span>
              </div>
              <div className="mt-2 h-1.5 rounded-full bg-border/60 overflow-hidden">
                <div
                  className="h-full rounded-full bg-primary"
                  style={{ width: `${metrics.newLast24h ? Math.min((metrics.aiAnalyzed / metrics.newLast24h) * 100, 100) : 0}%` }}
                />
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}
